// Transport validation only. Backend configuration is never taken from user input.
const incoming = $input.first().json;
const fromWebhook = Object.prototype.hasOwnProperty.call(incoming, 'body');
const surface = fromWebhook ? 'webhook' : 'form';
const body = fromWebhook ? incoming.body : incoming;
const fail = (message) => [{ json: {
  ok: false, http_status: 422, schema_version: '1.7.0', status: 'error',
  code: 'INVALID_INPUT', message, run_id: null, links: null, surface,
} }];
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return fail('请提交公司名称/股票代码和研究问题。');
}
const allowed = [
  'company_query', 'market_hint', 'requested_period_label', 'research_question',
  'research_time', 'idempotency_key',
];
const formMetadata = ['submittedAt', 'formMode'];
const rawSupplied = Object.fromEntries(Object.entries(body)
  .filter(([key]) => !formMetadata.includes(key)));
const formFields = [
  'Company / 公司或股票代码', 'Market / 市场', 'Period / 报告期（可选）',
  'Research Question / 研究问题',
];
if (Object.keys(rawSupplied).some((key) => !(fromWebhook ? allowed : formFields).includes(key))) {
  return fail('包含不支持的字段；后端地址和运行模式不可由请求覆盖。');
}
const formMarket = rawSupplied['Market / 市场'];
const marketAliases = {
  'Auto / 自动识别': null,
  'A 股': 'CN',
  '美股': 'US',
  '港股': 'HK',
};
const supplied = fromWebhook ? rawSupplied : {
  company_query: rawSupplied['Company / 公司或股票代码'],
  market_hint: marketAliases[formMarket] ?? null,
  requested_period_label: rawSupplied['Period / 报告期（可选）'] || null,
  research_question: rawSupplied['Research Question / 研究问题'],
};
if (typeof supplied.company_query !== 'string' ||
    supplied.company_query.trim().length < 1 || supplied.company_query.length > 200 ||
    ![undefined, null, 'CN', 'US', 'HK'].includes(supplied.market_hint) ||
    typeof supplied.research_question !== 'string' ||
    supplied.research_question.trim().length < 1 || supplied.research_question.length > 4000) {
  return fail('请检查公司名称/股票代码、市场和研究问题。');
}
const normalizedPeriod = typeof supplied.requested_period_label === 'string'
  ? supplied.requested_period_label.trim() : supplied.requested_period_label;
if (normalizedPeriod && !/^20[0-9]{2}(Q[1-4]|H1|FY)$/.test(normalizedPeriod)) {
  return fail('报告期请使用 2025FY / 2025H1 / 2025Q1 等格式，留空表示 Latest。');
}
if (supplied.idempotency_key !== undefined &&
    (typeof supplied.idempotency_key !== 'string' || supplied.idempotency_key.length < 8 ||
     supplied.idempotency_key.length > 256 || !supplied.research_time)) {
  return fail('重试时必须同时提供原 idempotency_key 和 research_time。');
}
if (supplied.research_time !== undefined &&
    (typeof supplied.research_time !== 'string' ||
     !/T.*(Z|[+-][0-9]{2}:[0-9]{2})$/.test(supplied.research_time) ||
     !Number.isFinite(Date.parse(supplied.research_time)))) {
  return fail('research_time 必须是含时区的 ISO 日期时间。');
}
return [{ json: {
  ok: true,
  surface,
  backend_url: 'http://api:8000',
  public_api_url: 'http://127.0.0.1:8000',
  started_at_ms: Date.now(),
  max_polls: 60,
  max_wait_ms: 150000,
  request: {
    company_query: supplied.company_query.trim(),
    market_hint: supplied.market_hint || null,
    requested_period_label: normalizedPeriod || null,
    research_question: supplied.research_question.trim(),
    research_time: supplied.research_time || new Date().toISOString(),
    idempotency_key: supplied.idempotency_key || `n8n-run-${$execution.id}`,
  },
} }];

const response = $input.first().json;
const ready = response.statusCode === 200 && response.body?.status === 'ok' && response.body?.version === '1.7.0';
if (!ready) {
  return [{ json: {
    ok: false,
    http_status: 502,
    schema_version: '1.7.0',
    status: 'error',
    code: 'BACKEND_UNAVAILABLE_OR_UNSAFE',
    run_id: null,
    links: null,
    message: 'ResearchForge 后端未就绪；未创建研究任务。',
  } }];
}
return [{ json: { ok: true } }];

const response = $input.first().json;
const config = $('Prepare request').first().json;
const id = response.body?.run_id;
if (response.statusCode !== 202 || typeof id !== 'string' ||
    !/^run_[a-f0-9]{32}$/.test(id)) {
  const conflict = response.statusCode === 409;
  const invalid = response.statusCode === 422;
  return [{ json: { ok: false, http_status: conflict ? 409 : invalid ? 422 : 502,
    schema_version: '1.7.0', status: 'error', run_id: null, links: null,
    code: conflict ? 'IDEMPOTENCY_CONFLICT' : invalid ? 'UNSUPPORTED_OR_INVALID_INPUT' : 'SUBMISSION_UNCONFIRMED',
    message: conflict ? '该幂等键已用于不同输入；请还原原请求或使用新键。' :
      invalid ? (response.body?.detail?.message || '后端拒绝了公司、市场、期间或研究输入。') :
        '提交未获确认；请求可能已被接收。请使用下方原请求重试，不要生成新幂等键。',
    retry_request: config.request,
  } }];
}
const path = `/v1/research-runs/${id}`;
return [{ json: { ok: true, run_id: id, path,
  links: {
    status: config.public_api_url + path,
    result: config.public_api_url + path + '/result',
    trace: config.public_api_url + path + '/trace',
    cancel: config.public_api_url + path + '/cancel',
  },
} }];

const response = $input.first().json;
const config = $('Prepare request').first().json;
const run = $('Accept submission').first().json;
const state = response.body?.lifecycle_state;
const polls = $runIndex + 1;
const base = { schema_version: '1.7.0', run_id: run.run_id, links: run.links, polls };
if (response.statusCode !== 200 || response.body?.run_id !== run.run_id) {
  return [{ json: { ...base, route: 'error', status: 'error', http_status: 502,
    code: 'STATUS_UNAVAILABLE',
    message: '无法确认后端任务状态；任务可能仍在运行。请检查状态链接，不要重复创建任务。',
  } }];
}
if (state === 'succeeded') return [{ json: { ...base, route: 'completed' } }];
if (state === 'queued' || state === 'running') {
  if (polls < config.max_polls && Date.now() - config.started_at_ms < config.max_wait_ms) {
    return [{ json: { ...base, route: 'waiting', lifecycle_state: state } }];
  }
  return [{ json: { ...base, route: 'error', status: 'error', http_status: 504,
    code: 'POLL_LIMIT_EXCEEDED',
    message: 'n8n 已达到等待上限；后端未被自动取消，可能仍在运行。请使用状态或取消链接。',
  } }];
}
const terminal = ['insufficient_data', 'failed', 'timed_out', 'cancelled'];
return [{ json: { ...base, route: 'error', status: 'error', http_status: 409,
  code: terminal.includes(state) ? `RUN_${state.toUpperCase()}` : 'UNKNOWN_BACKEND_STATE',
  message: state === 'insufficient_data' ? '可验证数据不足；没有生成研究报告。请检查来源和支持范围。' :
    state === 'cancelled' ? '后端任务已取消；没有可用研究报告。' :
      '后端任务没有可用研究结果。请检查状态和 Trace；n8n 不会编造报告或自动重跑研究。',
} }];

// Presentation aliases only: never calculate finance or generate a conclusion here.
const run = $('Accept submission').first().json;
const config = $('Prepare request').first().json;
const responses = ['Fetch result', 'Fetch facts', 'Fetch calculations', 'Fetch evidence', 'Fetch trace']
  .map((name) => $(name).first().json);
const [result, facts, calculations, evidence, trace] = responses.map((response) => response.body);
if (responses.some((response) => response.statusCode !== 200) ||
    result?.run_id !== run.run_id || result?.status !== 'completed' ||
    trace?.run_id !== run.run_id || !Array.isArray(trace?.stages) ||
    result?.schema_version !== '1.7.0' || result?.task_type !== 'company_research' ||
    typeof result?.executive_summary !== 'string' ||
    !Array.isArray(result?.claims) || !Array.isArray(result?.limitations) ||
    !Array.isArray(result?.monitoring_items) || !result?.research_intent ||
    !Array.isArray(result?.research_plan) || !Array.isArray(result?.analysis_sections) ||
    !result?.overall_judgment || !Array.isArray(result?.suggested_follow_ups) ||
    !result?.evidence_coverage ||
    !Array.isArray(facts) || !Array.isArray(calculations) || !Array.isArray(evidence)) {
  return [{ json: { schema_version: '1.7.0', status: 'error', http_status: 502,
    run_id: run.run_id, links: run.links, code: 'RESULT_ARTIFACTS_UNAVAILABLE',
    message: '后端报告或审计产物不可用/不匹配；未把缺失内容呈现为成功。请检查结果和 Trace 链接。',
  } }];
}
return [{ json: {
  schema_version: '1.7.0', status: 'succeeded', http_status: 200, data_namespace: 'product',
  run_id: run.run_id, links: run.links, request: config.request,
  conclusion: result.executive_summary,
  findings: result.claims,
  research_intent: result.research_intent,
  research_plan: result.research_plan,
  analysis_sections: result.analysis_sections,
  overall_judgment: result.overall_judgment,
  suggested_follow_ups: result.suggested_follow_ups,
  evidence_coverage: result.evidence_coverage,
  financial_facts: facts,
  calculations,
  supporting_evidence: evidence,
  counter_evidence: result.claims.map((claim) => ({
    claim_id: claim.claim_id, search: claim.counter_evidence_search,
  })),
  limitations: result.limitations,
  monitoring: result.monitoring_items,
  research_result: result,
  research_trace: trace,
  trust_boundary: 'n8n 只编排并转交 ResearchForge 产物，不生成结论或计算财务数字。失败时不生成伪结论。',
} }];

// Render backend-owned artifacts for the native form without creating research content.
const incoming = $input.first().json;
// `surface` is internal routing metadata and is never part of the public webhook contract.
const transport = { ...incoming };
delete transport.surface;
const escape = (value) => String(value ?? '')
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;').replaceAll("'", '&#39;');
const safeUrl = (value) => /^https?:\/\//.test(String(value ?? '')) ? escape(value) : '#';
const list = (items) => items.length > 0 ? `<ul>${items.map((item) => `<li>${item}</li>`).join('')}</ul>` : '<p>无可呈现项目。</p>';

let content;
if (transport.status !== 'succeeded') {
  content = `
    <header><p class="eyebrow">BOUNDED FAILURE</p><h1>研究未生成</h1></header>
    <section class="failure">
    <p><strong>${escape(transport.code)}</strong> — ${escape(transport.message)}</p>
    <p>ResearchForge 在输入、数据、状态或产物无法确认时会停止，不会补写结论或数字。</p>
    ${transport.links?.status ? `<p><a href="${safeUrl(transport.links.status)}">检查后端运行状态</a></p>` : ''}
    </section>`;
} else {
  const facts = transport.financial_facts.map((fact) => `<strong>${escape(fact.metric_code)}</strong>: ${escape(fact.value ?? 'ABSTAINED')} ${escape(fact.currency ?? fact.measurement_unit ?? '')} · P${escape(fact.source_locator?.page ?? '—')}`);
  const calculations = transport.calculations.map((calculation) => `<strong>${escape(calculation.formula_code)}</strong>: ${escape(calculation.value ?? '不适用')} · ${escape(calculation.explanation)}`);
  const findings = transport.findings.map((finding) => escape(finding.text));
  const plan = transport.research_plan.map((step) => `<strong>${escape(step.description)}</strong> · ${escape(step.status)}`);
  const analysis = transport.analysis_sections.map((section) => `<strong>${escape(section.title)}</strong><br>${escape(section.text)}`);
  const followUps = transport.suggested_follow_ups.map(escape);
  const evidence = transport.supporting_evidence.map((chunk) => `<strong>${escape(chunk.section)} · P${escape(chunk.locator?.page_start ?? '—')}</strong><br>${escape(chunk.text)}<br><a href="${safeUrl(chunk.source_uri)}">打开官方披露</a>`);
  const counters = transport.counter_evidence.map((entry) => `<strong>${escape(entry.search?.result)}</strong>: ${escape(entry.search?.summary)}`);
  const monitoring = transport.monitoring.map((item) => `<strong>${escape(item.title)}</strong>: ${escape(item.rationale)} · 触发条件 ${escape(item.trigger)} · ${escape(item.next_review)}`);
  content = `
    <header><p class="eyebrow">SAME BACKEND · VERIFIED PIPELINE</p><h1>ResearchForge 研究完成</h1><span class="status">SUCCEEDED</span></header>
    <section class="conclusion"><h2>Executive Conclusion / 核心结论</h2><p>${escape(transport.conclusion)}</p></section>
    <section class="judgment"><h2>Research Intent / 研究意图</h2><p><strong>${escape(transport.research_intent.label)}</strong> · ${escape(transport.research_intent.skill)}</p><p>${escape(transport.overall_judgment.label)} — ${escape(transport.overall_judgment.rationale)}</p></section>
    <details open><summary>Research Plan / 研究计划</summary>${list(plan)}</details>
    <details open><summary>Key Findings / 关键发现</summary>${list(findings)}</details>
    <details open><summary>Deep Analysis / 深入分析</summary>${list(analysis)}</details>
    <details><summary>Financial Facts / 财务事实</summary>${list(facts)}</details>
    <details><summary>Calculations / 确定性计算</summary>${list(calculations)}</details>
    <details><summary>Supporting Evidence / 支持证据</summary>${list(evidence)}</details>
    <details open><summary>Counter Evidence & Limitations / 反证与限制</summary>${list([...counters, ...transport.limitations.map(escape)])}</details>
    <details open><summary>Monitoring Plan / 后续监控</summary>${list(monitoring)}</details>
    <details open><summary>Suggested Follow-ups / 继续追问</summary>${list(followUps)}</details>
    <p class="coverage">Evidence coverage: ${escape(transport.evidence_coverage.selected_chunk_count)} selected / ${escape(transport.evidence_coverage.available_chunk_count)} available · sections ${escape((transport.evidence_coverage.sections || []).join(', '))}</p>
    <nav><a href="${safeUrl(transport.links.result)}">完整 Research Result</a><a href="${safeUrl(transport.links.trace)}">完整 Research Trace</a></nav>
    <footer>${escape(transport.trust_boundary)}</footer>`;
}
const formPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ResearchForge 研究结果</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#dce4eb;background:#071015}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 75% -10%,#173d33 0,transparent 35%),#071015}main{max-width:920px;margin:auto;padding:44px 22px 70px}header{position:relative;margin-bottom:22px}.eyebrow{color:#43d6a3;font:11px ui-monospace,monospace;letter-spacing:.14em}h1{margin:8px 0;color:#fff;font-size:30px}.status{position:absolute;right:0;top:15px;padding:5px 9px;border:1px solid #2c8064;border-radius:99px;color:#72e7bd;font:10px ui-monospace,monospace}.conclusion,.judgment,details,.failure{margin:12px 0;padding:18px;border:1px solid #23343e;border-radius:12px;background:#0d1921}.conclusion{border-left:3px solid #43d6a3}.judgment{border-left:3px solid #d4a85f}.judgment h2{margin:0 0 10px;color:#d4a85f;font-size:12px}.judgment p,.coverage{color:#9eb0b9;line-height:1.7}.conclusion h2{margin:0 0 10px;color:#8fa5b1;font-size:12px}.conclusion p{margin:0;color:#e3eaed;font:17px/1.85 Georgia,serif}summary{cursor:pointer;color:#c9d5da;font-weight:650}ul{margin:14px 0 0;padding-left:20px}li{margin:9px 0;color:#9eb0b9;line-height:1.65}a{color:#71d7b2}nav{display:flex;gap:12px;margin-top:18px}nav a{padding:10px 12px;border:1px solid #285846;border-radius:8px;text-decoration:none}footer{margin-top:20px;color:#657d88;font:10px/1.7 ui-monospace,monospace}.failure{border-color:#663b3b;color:#ffaaa4}@media(max-width:600px){main{padding:28px 14px}.status{position:static;display:inline-block}nav{flex-direction:column}}
</style></head><body><main>${content}</main></body></html>`;
return [{ json: { transport, formPage } }];
